// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAncestry Walk an image's ancestry to its root base
	// (GET /v1/ancestry)
	GetAncestry(ctx context.Context, request GetAncestryRequestObject) (GetAncestryResponseObject, error)
	// GetDescendants Find everything built on a base
	// (GET /v1/descendants)
	GetDescendants(ctx context.Context, request GetDescendantsRequestObject) (GetDescendantsResponseObject, error)
	// GetHealth Report server health and index size
	// (GET /v1/healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetImage Explain one image
	// (GET /v1/images/{digest})
	GetImage(ctx context.Context, request GetImageRequestObject) (GetImageResponseObject, error)
	// GetMap Aggregated registry map
	// (GET /v1/map)
	GetMap(ctx context.Context, request GetMapRequestObject) (GetMapResponseObject, error)
	// GetOutline One level of the lineage outline
	// (GET /v1/outline)
	GetOutline(ctx context.Context, request GetOutlineRequestObject) (GetOutlineResponseObject, error)
	// GetOverview Registry overview for the web UI
	// (GET /v1/overview)
	GetOverview(ctx context.Context, request GetOverviewRequestObject) (GetOverviewResponseObject, error)
	// RunQuery Filter images with the query language
	// (GET /v1/query)
	RunQuery(ctx context.Context, request RunQueryRequestObject) (RunQueryResponseObject, error)
	// GetQueryGraph Draw the images a filter matches plus their ancestry
	// (GET /v1/query/graph)
	GetQueryGraph(ctx context.Context, request GetQueryGraphRequestObject) (GetQueryGraphResponseObject, error)
	// ResolveRef Resolve a ref to a platform manifest digest
	// (GET /v1/resolve)
	ResolveRef(ctx context.Context, request ResolveRefRequestObject) (ResolveRefResponseObject, error)
	// GetRoots List root bases and their descendant counts
	// (GET /v1/roots)
	GetRoots(ctx context.Context, request GetRootsRequestObject) (GetRootsResponseObject, error)
	// Search Filter images with facet counts
	// (GET /v1/search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// GetStale Report the staleness mix
	// (GET /v1/stale)
	GetStale(ctx context.Context, request GetStaleRequestObject) (GetStaleResponseObject, error)
	// GetStatus Progress of the running index
	// (GET /v1/status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// GetSummary Footprint summary of the registry
	// (GET /v1/summary)
	GetSummary(ctx context.Context, request GetSummaryRequestObject) (GetSummaryResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

